    INSERT INTO topics (title, slug, year_id, section, "order")
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which of the following is the only vaccine recommended to be given at birth to all medically stable infants?', '["Hepatitis A", "Hepatitis B", "BCG", "IPV"]', 1, 'Hepatitis B vaccine is recommended for all medically stable infants weighing >=2000g within 24 hours of birth. (Nelson)'),
    (v_topic_id, '2: A neonate is born to a mother who is HBsAg positive. What is the most appropriate immediate management?', '["Hepatitis B vaccine only", "HBIG only", "Hepatitis B vaccine and HBIG within 12 hours of birth", "Wait for infant''s HBsAg results"]', 2, 'Infants born to HBsAg+ mothers require both the vaccine and Hepatitis B Immune Globulin (HBIG) at separate injection sites within 12 hours. (Harriet Lane)'),
    (v_topic_id, '3: What is the minimum age for the first dose of the Rotavirus (RV) vaccine?', '["Birth", "6 weeks", "2 months", "4 months"]', 1, 'The first dose of RV vaccine can be given as early as 6 weeks and should be started by 14 weeks 6 days. (CDC/Nelson)'),
    (v_topic_id, '4: By what age must the final dose of the Rotavirus vaccine series be completed?', '["6 months", "8 months 0 days", "12 months", "18 months"]', 1, 'The maximum age for the final dose of the RV series is 8 months and 0 days. (Nelson)'),
    (v_topic_id, '5: Which of the following is a strict contraindication to the Rotavirus vaccine?', '["History of mild fever after previous dose", "History of intussusception", "Living with a pregnant woman", "Mild upper respiratory infection"]', 1, 'A history of intussusception is a contraindication to the RV vaccine due to a small but significant increased risk. (Case Files)'),
    (v_topic_id, '6: A 2-month-old infant presents for routine immunizations. Which of the following vaccines are typically given at this visit?', '["DTaP, Hib, PCV13, IPV, RV, HepB", "MMR, Varicella, DTaP", "HepA, Hib, PCV13", "DTaP, IPV, MMR"]', 0, 'The 2-month visit includes the second dose of HepB (if given at birth) and the first doses of DTaP, Hib, PCV13, IPV, and RV. (CDC Schedule)'),
    (v_topic_id, '7: At what age is the first dose of the Measles-Mumps-Rubella (MMR) vaccine typically recommended?', '["6 months", "12-15 months", "4-6 years", "11-12 years"]', 1, 'The first dose of MMR is recommended between 12 and 15 months of age. (Harriet Lane)'),
    (v_topic_id, '8: Why is the MMR vaccine not routinely administered before 12 months of age?', '["It is too expensive", "Interference from maternal antibodies", "Risk of autism", "The infant''s immune system cannot respond to proteins"]', 1, 'Passively acquired maternal antibodies can interfere with the immune response to live-virus vaccines like MMR and Varicella. (Nelson)'),
    (v_topic_id, '9: In the event of a local Measles outbreak, what is the earliest age an infant can receive the MMR vaccine?', '["3 months", "6 months", "9 months", "12 months"]', 1, 'During outbreaks or for international travel, MMR can be given as early as 6 months (though it does not count toward the 2-dose series). (CDC)'),
    (v_topic_id, '10: Which of the following vaccines is a live-attenuated vaccine?', '["IPV", "DTaP", "Varicella", "Hepatitis B"]', 2, 'Varicella, MMR, and Rotavirus are common live-attenuated vaccines used in children. (Case Files)'),
    (v_topic_id, '11: Which vaccine is contraindicated in a child with a known history of severe anaphylactic allergy to neomycin or gelatin?', '["MMR", "DTaP", "PCV13", "Hib"]', 0, 'MMR and Varicella vaccines contain trace amounts of neomycin and gelatin. (Nelson)'),
    (v_topic_id, '12: A 4-year-old child is due for "kindergarten shots." Which vaccines are routinely given at the 4-6 year visit?', '["DTaP, IPV, MMR, Varicella", "DTaP, IPV, PCV13", "Tdal, HPV, Meningococcal", "HepA, HepB"]', 0, 'The 4-6 year visit involves the 5th DTaP, 4th IPV, 2nd MMR, and 2nd Varicella. (CDC)'),
    (v_topic_id, '13: At what age is the first dose of Hepatitis A (HepA) vaccine recommended?', '["Birth", "6 months", "12 months", "24 months"]', 2, 'The HepA 2-dose series is started at 12 months, with the second dose at least 6 months later. (Harriet Lane)'),
    (v_topic_id, '14: Which of the following is a contraindication to the DTaP vaccine?', '["Encephalopathy within 7 days of a previous dose", "Fever of 102F after previous dose", "Stable neurologic condition", "Family history of seizures"]', 0, 'Encephalopathy not attributable to another cause within 7 days is a strict contraindication to the pertussis component of DTaP. (Nelson)'),
    (v_topic_id, '15: A 12-month-old child has a mild cold and a temperature of 99.8 F. Can they receive their scheduled vaccines?', '["No, wait until the fever is gone", "Yes, mild illness is not a contraindication", "No, live vaccines must be avoided", "Only inactivated vaccines can be given"]', 1, 'Minor acute illnesses (with or without low-grade fever) are NOT contraindications to vaccination. (Case Files)'),
    (v_topic_id, '16: Which of the following vaccines is given as an intramuscular (IM) injection?', '["MMR", "Varicella", "DTaP", "IPV (usually)"]', 2, 'DTaP, HepB, Hib, PCV, and HepA are IM. MMR and Varicella are subcutaneous (SC). IPV can be either but is usually IM/SC. (Harriet Lane)'),
    (v_topic_id, '17: What is the recommended site for IM vaccine administration in an infant (under 12 months)?', '["Deltoid muscle", "Anterolateral thigh (Vastus lateralis)", "Gluteal muscle", "Forearm"]', 1, 'The vastus lateralis is the preferred site due to its large muscle mass in infants. (Nelson)'),
    (v_topic_id, '18: At what age can the deltoid muscle be used for IM injections?', '["6 months", "12-18 months (if muscle mass is adequate)", "3 years", "5 years"]', 1, 'The deltoid is usually used once the child is walking and has developed sufficient muscle mass, typically >1 year. (CDC)'),
    (v_topic_id, '19: A 14-month-old child receives the MMR and Varicella vaccines. What is the minimum interval before they can receive another live-virus vaccine if not given on the same day?', '["1 week", "2 weeks", "4 weeks (28 days)", "6 months"]', 2, 'Live-virus vaccines not given on the same day must be separated by at least 4 weeks to avoid interference. (Nelson)'),
    (v_topic_id, '20: Which component of the DTaP vaccine is most commonly associated with local reactions (redness/swelling)?', '["Diphtheria", "Tetanus", "Acellular Pertussis", "Aluminum adjuvant"]', 2, 'Pertussis antigens are the most common cause of local site reactions and fever. (Case Files)'),
    (v_topic_id, '21: At what age is the first dose of the Meningococcal (MenACWY) vaccine routinely recommended?', '["2 months", "1 year", "11-12 years", "16 years"]', 2, 'The first MenACWY dose is at 11-12 years, with a booster at age 16. (CDC)'),
    (v_topic_id, '22: When is the first dose of the Human Papillomavirus (HPV) vaccine series recommended?', '["9-12 years (routinely 11-12)", "15 years", "18 years", "21 years"]', 0, 'The HPV series can start at age 9 and is routinely recommended at 11-12 years. (Nelson)'),
    (v_topic_id, '23: For a child starting the HPV series before age 15, how many doses are required?', '["1 dose", "2 doses", "3 doses", "4 doses"]', 1, 'If started before age 15, a 2-dose series (6-12 months apart) is sufficient. (CDC)'),
    (v_topic_id, '24: For a person starting the HPV series at age 15 or older, how many doses are required?', '["1 dose", "2 doses", "3 doses", "4 doses"]', 2, 'Individuals starting the series at age 15+ require 3 doses (0, 1-2, and 6 months). (Harriet Lane)'),
    (v_topic_id, '25: At what age should a child receive their first "flu shot" (Influenza vaccine)?', '["Birth", "6 months", "1 year", "2 years"]', 1, 'The influenza vaccine is recommended annually for everyone aged 6 months and older. (Nelson)'),
    (v_topic_id, '26: A 2-year-old child is receiving the influenza vaccine for the first time. How many doses do they need this season?', '["1 dose", "2 doses (4 weeks apart)", "3 doses", "No doses needed"]', 1, 'Children aged 6 months through 8 years receiving the flu vaccine for the first time (or who have only had 1 dose ever) need 2 doses. (CDC)'),
    (v_topic_id, '27: Which influenza vaccine is live-attenuated and administered intranasally?', '["IIV3", "IIV4", "LAIV", "ccIIV4"]', 2, 'LAIV (FluMist) is the live-attenuated intranasal influenza vaccine. (Harriet Lane)'),
    (v_topic_id, '28: Which of the following is a contraindication to the Live Attenuated Influenza Vaccine (LAIV)?', '["Egg allergy", "Asthma or reactive airway disease in a child <5 years", "Family history of flu", "Mild cold"]', 1, 'LAIV is contraindicated in children with asthma or wheezing in the past year due to risk of bronchospasm. (Nelson)'),
    (v_topic_id, '29: A child with a history of severe egg allergy (anaphylaxis) needs the flu vaccine. What is the current recommendation?', '["They cannot receive any flu vaccine", "They should receive the inactivated vaccine in a medical setting", "They can receive any age-appropriate flu vaccine", "They must wait until age 18"]', 2, 'The AAP and CDC now state that children with egg allergy of any severity can receive any age-appropriate influenza vaccine. (CDC/Nelson)'),
    (v_topic_id, '30: Which vaccine provides protection against bacterial meningitis caused by Serogroup B?', '["MenACWY", "MenB", "Hib", "PCV13"]', 1, 'MenB is a separate vaccine specifically for Serogroup B, often given between 16 and 23 years. (Harriet Lane)'),
    (v_topic_id, '31: A 15-month-old child is behind on vaccines. They haven''t had any PCV doses. How many doses of PCV13/15 are needed if starting at this age?', '["1 dose", "2 doses", "3 doses", "4 doses"]', 0, 'For healthy children starting PCV at 12-23 months, only 1 dose is needed (if they haven''t had any). (CDC Catch-up)'),
    (v_topic_id, '32: Which vaccine contains a toxoid?', '["MMR", "Hepatitis B", "Tetanus (in DTaP)", "IPV"]', 2, 'Diphtheria and Tetanus vaccines are toxoids (inactivated toxins). (Nelson)'),
    (v_topic_id, '33: The Hib vaccine protects against which of the following conditions?', '["Influenza virus", "Epiglottitis and meningitis caused by H. influenzae type b", "Pneumonia caused by S. pneumoniae", "Whooping cough"]', 1, 'Haemophilus influenzae type b is a bacterium that causes invasive disease like epiglottitis and meningitis. (Case Files)'),
    (v_topic_id, '34: Which vaccine has been shown to significantly reduce the incidence of cervical cancer?', '["MMR", "HepB", "HPV", "MenACWY"]', 2, 'HPV vaccine prevents infection with high-risk types of human papillomavirus. (Nelson)'),
    (v_topic_id, '35: At what age is the "booster" dose of the Meningococcal (MenACWY) vaccine given?', '["12 years", "14 years", "16 years", "18 years"]', 2, 'The booster is given at 16 to ensure protection through the high-risk late-adolescent years. (CDC)'),
    (v_topic_id, '36: A child has a known T-cell immunodeficiency. Which vaccine should be AVOIDED?', '["HepB", "IPV", "PCV13", "MMR"]', 3, 'Live-virus vaccines (MMR, Varicella, RV, LAIV) are generally contraindicated in severely immunocompromised patients. (Harriet Lane)'),
    (v_topic_id, '37: Which of the following is NOT a contraindication to vaccination?', '["Pregnancy (for live vaccines)", "Severe immunosuppression (for live vaccines)", "Mild acute illness", "Anaphylaxis to a vaccine component"]', 2, 'Mild illness is a common "false contraindication." (Case Files)'),
    (v_topic_id, '38: A child receives a blood transfusion. How long should you typically wait before giving the MMR vaccine?', '["1 week", "1 month", "3-11 months (depending on product)", "1 year"]', 2, 'Passively acquired antibodies in blood products can interfere with MMR/Varicella for several months. (Nelson)'),
    (v_topic_id, '39: Which vaccine is associated with a small risk of febrile seizures 7-12 days after administration?', '["DTaP", "MMR", "Hib", "IPV"]', 1, 'MMR can cause fever and occasionally febrile seizures 1-2 weeks post-vaccination. (Nelson)'),
    (v_topic_id, '40: What is the "cocooning" strategy for pertussis?', '["Wrapping the infant in a blanket", "Vaccinating all household members and caregivers of a newborn", "Giving the infant extra doses of DTaP", "Keeping the infant in a sterile room"]', 1, 'Vaccinating adults (Tdap) around the baby prevents transmission to the vulnerable infant. (Nelson)'),
    (v_topic_id, '41: At what point in pregnancy is the Tdap vaccine recommended for the mother?', '["First trimester", "Second trimester", "27-36 weeks gestation", "Postpartum only"]', 2, 'Tdap during the 3rd trimester allows for optimal transplacental transfer of pertussis antibodies to the fetus. (CDC)'),
    (v_topic_id, '42: Which vaccine is given to prevent "Whooping Cough"?', '["Hib", "DTaP", "PCV13", "IPV"]', 1, 'The "P" in DTaP stands for Pertussis, the cause of whooping cough. (Case Files)'),
    (v_topic_id, '43: A child is born at 32 weeks gestation and is now 2 months old (chronological age). Should they follow the standard immunization schedule?', '["No, use corrected gestational age", "Yes, use chronological age for most vaccines", "Only if they weigh >5kg", "Wait until 6 months"]', 1, 'Premature infants should be vaccinated according to chronological age, except for HepB in some low-birth-weight cases. (Nelson)'),
    (v_topic_id, '44: If a premature infant weighs <2000g at birth to an HBsAg-negative mother, when is the first HepB dose ideally given?', '["At birth", "At 1 month of age or at hospital discharge", "At 6 months", "Never"]', 1, 'If the mother is negative and the baby is <2000g, the first HepB dose is delayed until 1 month or discharge. (CDC)'),
    (v_topic_id, '45: A child has a sibling who is immunocompromised. Can the child receive the MMR vaccine?', '["No", "Yes, MMR is not transmitted to contacts", "Only if the sibling leaves the house", "Only the inactivated MMR"]', 1, 'Live vaccines like MMR and Varicella are safe to give to household contacts of immunocompromised patients. (LAIV and OPV are exceptions). (Nelson)'),
    (v_topic_id, '46: Which vaccine is primarily associated with the prevention of epiglottitis?', '["PCV13", "Hib", "DTaP", "MMR"]', 1, 'The introduction of the Hib vaccine led to a dramatic decrease in H. influenzae type b epiglottitis. (Case Files)'),
    (v_topic_id, '47: What is the maximum age to receive the first dose of DTaP?', '["1 year", "5 years", "6 years (before 7th birthday)", "18 years"]', 2, 'DTaP is for children <7 years. Tdap is used for older children and adults. (Harriet Lane)'),
    (v_topic_id, '48: A 10-year-old child has never been vaccinated. Which pertussis-containing vaccine should they receive?', '["DTaP", "Tdap", "Td only", "Hib"]', 1, 'Children aged 7+ use the Tdap (reduced antigen) formulation. (CDC)'),
    (v_topic_id, '49: Which of the following is a common, self-limiting side effect of the second HepA dose?', '["High fever", "Soreness at the injection site", "Jaundice", "Seizures"]', 1, 'Injection site pain is the most common side effect of most inactivated vaccines. (Nelson)'),
    (v_topic_id, '50: How long must you wait between the two doses of the HepA vaccine?', '["1 month", "2 months", "At least 6 months", "1 year"]', 2, 'The minimum interval for HepA is 6 months. (CDC)'),
    (v_topic_id, '51: Which of the following is NOT a component of the PCV13/15 vaccine?', '["Serotypes 1, 3, 4", "Serotypes 19A, 19F", "Serotype 6B", "N. meningitidis antigens"]', 3, 'PCV protects against Streptococcus pneumoniae, not Neisseria meningitidis. (Nelson)'),
    (v_topic_id, '52: At what age should "universal" screening for anemia (hemoglobin/hematocrit) occur?', '["6 months", "12 months", "2 years", "5 years"]', 1, 'Universal screening for iron deficiency anemia is recommended at age 1. (AAP/Harriet Lane)'),
    (v_topic_id, '53: Universal lead screening is often recommended at what ages in high-risk areas?', '["6 and 12 months", "12 and 24 months", "3 and 5 years", "10 years"]', 1, 'Targeted or universal screening is typically done at 1 and 2 years. (Case Files)'),
    (v_topic_id, '54: A child''s vision is first formally screened with a chart (e.g., Snellen or LEA symbols) starting at what age?', '["1 year", "2 years", "3 years", "5 years"]', 2, 'Formal visual acuity testing usually begins at the 3-year well-child visit. (Nelson)'),
    (v_topic_id, '55: What is the recommended "screen time" limit for children aged 2 to 5 years?', '["Zero", "1 hour per day of high-quality programming", "2 hours per day", "Unlimited"]', 1, 'The AAP recommends limiting screen time to 1 hour of educational content for this age group. (AAP)'),
    (v_topic_id, '56: At what age should a pediatrician start performing a formal "m-CHAT" (Modified Checklist for Autism in Toddlers)?', '["12 months", "18 and 24 months", "36 months", "5 years"]', 1, 'Autism-specific screening is recommended at the 18- and 24-month visits. (Nelson)'),
    (v_topic_id, '57: Which of the following is a "red flag" for hearing loss in a 6-month-old?', '["Not saying words", "Not turning toward a sound", "Not following a light", "Not sitting"]', 1, 'Turn-to-sound is a key auditory milestone at 6 months. (Case Files)'),
    (v_topic_id, '58: When should a child have their first formal hearing screen?', '["At birth (Newborn Hearing Screen)", "6 months", "3 years", "5 years"]', 0, 'Universal newborn hearing screening is standard before hospital discharge. (Harriet Lane)'),
    (v_topic_id, '59: What is the recommended sleeping position for an infant to prevent SIDS?', '["Prone (on tummy)", "Side-lying", "Supine (on back)", "In a swing"]', 2, 'The "Back to Sleep" campaign has significantly reduced SIDS rates. (Nelson)'),
    (v_topic_id, '60: Which of the following is a safe sleep practice?', '["Sleeping with a soft pillow", "Using a loose blanket", "Sleeping on a firm, flat surface without bumpers or stuffed animals", "Sleeping in the same bed as parents"]', 2, 'Co-sleeping and soft bedding are major risk factors for SUIDS. (AAP)'),
    (v_topic_id, '61: At what age can fruit juice be introduced into a child''s diet?', '["Birth", "4 months", "6 months", "Avoid until 1 year; then limited"]', 3, 'The AAP recommends NO fruit juice for children <1 year and limiting it thereafter. (Nelson)'),
    (v_topic_id, '62: What is the recommended dose of Vitamin D supplementation for breastfed infants?', '["100 IU/day", "200 IU/day", "400 IU/day", "1000 IU/day"]', 2, 'Exclusively or partially breastfed infants need 400 IU of Vitamin D daily starting in the first few days of life. (Harriet Lane)'),
    (v_topic_id, '63: When should iron supplementation (1 mg/kg/day) be started for an exclusively breastfed TERM infant?', '["At birth", "2 months", "4 months", "6 months"]', 2, 'Term infants have iron stores that last about 4 months; after that, supplementation is needed if not on iron-fortified solids. (Nelson)'),
    (v_topic_id, '64: Fluoride supplementation should be considered starting at what age if the local water supply is deficient?', '["Birth", "6 months", "1 year", "3 years"]', 1, 'Fluoride supplementation starts at 6 months if levels are <0.3 ppm. (Harriet Lane)'),
    (v_topic_id, '65: At what age should a child have their first dental visit?', '["1 year or when the first tooth erupts", "3 years", "5 years", "When permanent teeth come in"]', 0, 'Establish a "dental home" by age 1. (Case Files)'),
    (v_topic_id, '66: Which of the following is the most effective way to prevent drowning in a home with a pool?', '["Swimming lessons", "Floaties", "A 4-sided fence with self-closing, self-latching gates", "Constant supervision only"]', 2, 'Isolation fencing is the gold standard for pool safety. (Nelson)'),
    (v_topic_id, '67: What is the recommended temperature for a home water heater to prevent scald burns?', '["100 F", "120 F", "140 F", "160 F"]', 1, 'Setting the heater to 120 F (49 C) or lower prevents rapid scalding. (Harriet Lane)'),
    (v_topic_id, '68: How long should a child remain in a rear-facing car seat?', '["Until 1 year", "Until they reach the maximum weight/height for the seat (ideally age 2 or older)", "Until 4 years", "Until 40 lbs"]', 1, 'Rear-facing is safest for as long as the seat allows. (AAP)'),
    (v_topic_id, '69: At what age is a child typically ready to transition from a booster seat to a vehicle seat belt?', '["8 years", "10 years", "When they reach 4''9'''' tall and the belt fits correctly", "12 years"]', 2, 'Height is the primary indicator of proper belt fit. (Nelson)'),
    (v_topic_id, '70: Universal lipid screening is recommended for children at what age range?', '["2-5 years", "9-11 years", "12-15 years", "Only if obese"]', 1, 'The AAP recommends universal screening at 9-11 years and again at 17-21 years. (Harriet Lane)'),
    (v_topic_id, '71: Which of the following is a "red flag" for developmental delay in a 9-month-old?', '["Not walking", "Not saying ''Mama''", "Not sitting without support", "Not crawling"]', 2, 'Sitting unsupported is usually mastered by 6-7 months; failure by 9 months is a concern. (Case Files)'),
    (v_topic_id, '72: "Anticipatory guidance" refers to:', '["Treating an illness after it happens", "Providing parents with information on upcoming developmental milestones and safety", "Predicting the child''s future career", "Ordering lab tests"]', 1, 'Anticipatory guidance is a cornerstone of preventive pediatrics. (Nelson)'),
    (v_topic_id, '73: Which vaccine is administered subcutaneously?', '["HepB", "PCV13", "MMR", "DTaP"]', 2, 'Live vaccines like MMR and Varicella are SC. (Harriet Lane)'),
    (v_topic_id, '74: A child with a "cochlear implant" is at increased risk for meningitis. Which vaccine is especially important?', '["PCV13 and PPSV23", "HepA", "Varicella", "RV"]', 0, 'Children with implants or CSF leaks require both conjugate and polysaccharide pneumococcal vaccines. (Nelson)'),
    (v_topic_id, '75: Which vaccine is recommended for a 12-year-old child that was not given in infancy?', '["HepB", "MMR", "Varicella", "All of the above (if missing)"]', 3, 'Catch-up vaccines should be completed at any visit. (CDC)'),
    (v_topic_id, '76: A 2-year-old child presents with a high fever. The parent states they have never been vaccinated. What is the most likely pathogen causing a hidden bacteremia?', '["S. pneumoniae", "Staph aureus", "E. coli", "Group B Strep"]', 0, 'In the post-PCV era, invasive pneumococcal disease has dropped, but it remains a risk in unvaccinated kids. (Case Files)'),
    (v_topic_id, '77: Which vaccine is associated with "intussusception" as a rare but known adverse effect?', '["MMR", "Rotavirus", "Varicella", "PCV13"]', 1, 'The risk is approximately 1 in 20,000 to 1 in 100,000 doses. (Nelson)'),
    (v_topic_id, '78: A child has a history of a "febrile seizure" after a previous flu shot. Is this a contraindication to future flu shots?', '["Yes", "No", "Only if the fever was >104", "Only for live flu vaccine"]', 1, 'A history of febrile seizures is NOT a contraindication to any vaccine. (Nelson)'),
    (v_topic_id, '79: Which vaccine is given to prevent a disease that can cause "lockjaw"?', '["Pertussis", "Tetanus", "Diphtheria", "Meningococcal"]', 1, 'Tetanus (C. tetani) causes severe muscle spasms, including the jaw. (Case Files)'),
    (v_topic_id, '80: Which vaccine contains protection against "German Measles"?', '["MMR", "Varicella", "DTaP", "PCV13"]', 0, 'The second "R" in MMR stands for Rubella (German Measles). (Harriet Lane)'),
    (v_topic_id, '81: How many doses of the DTaP vaccine are in the primary series before age 2?', '["2", "3", "4", "5"]', 2, 'Doses are at 2, 4, 6, and 15-18 months. (CDC)'),
    (v_topic_id, '82: A 6-year-old child has a clean, minor wound. Their last tetanus-containing vaccine was at age 4. Do they need a booster?', '["Yes", "No", "Only if the wound was dirty", "Only if they have a fever"]', 1, 'For minor clean wounds, a booster is needed only if the last dose was >10 years ago. (Nelson)'),
    (v_topic_id, '83: For a dirty or contaminated wound, when is a tetanus booster needed?', '["If last dose was >1 year ago", "If last dose was >5 years ago", "If last dose was >10 years ago", "Never"]', 1, 'For high-risk wounds, the threshold is 5 years. (Harriet Lane)'),
    (v_topic_id, '84: What is the most common reason for vaccine hesitancy among parents?', '["Cost", "Lack of access", "Concerns about safety/side effects", "Religious beliefs"]', 2, 'Safety concerns (often based on misinformation) are the most frequent driver. (Nelson)'),
    (v_topic_id, '85: Which vaccine protects against "mumps", which can cause orchitis and parotitis?', '["MMR", "HepB", "HPV", "PCV13"]', 0, 'Mumps is the middle "M" in MMR. (Case Files)'),
    (v_topic_id, '86: Which of the following vaccines is NOT routinely given in the US but may be given for travel to certain countries?', '["Yellow Fever", "IPV", "MMR", "PCV13"]', 0, 'Yellow fever, Typhoid, and Japanese Encephalitis are travel vaccines. (Nelson)'),
    (v_topic_id, '87: The "PV" in PCV13 stands for:', '["Polio Vaccine", "Pneumococcal Vaccine", "Papillomavirus", "Pertussis"]', 1, 'Pneumococcal Conjugate Vaccine. (Harriet Lane)'),
    (v_topic_id, '88: Which of the following is a risk of NOT vaccinating against Hib?', '["Liver failure", "Epiglottitis", "Cervical cancer", "Shingles"]', 1, 'Hib was the most common cause of epiglottitis before the vaccine. (Case Files)'),
    (v_topic_id, '89: A child presents with a "slapped cheek" rash. Is there a vaccine for this?', '["Yes, MMR", "Yes, Varicella", "No, it is Fifth Disease (Parvovirus B19)", "Yes, Hib"]', 2, 'There is currently no vaccine for Parvovirus B19. (Nelson)'),
    (v_topic_id, '90: Which vaccine is associated with preventing "shingles" later in life?', '["MMR", "Varicella", "IPV", "HepA"]', 1, 'The Varicella vaccine prevents the primary infection (chickenpox), which reduces the reservoir for later shingles (zoster). (Nelson)'),
    (v_topic_id, '91: At what age is the "Tdap" (adolescent booster) routinely given?', '["4-6 years", "11-12 years", "16 years", "21 years"]', 1, 'Tdap is the first vaccine given at the adolescent well-check. (CDC)'),
    (v_topic_id, '92: Which vaccine is indicated for a child with functional or anatomic asplenia (e.g., Sickle Cell)?', '["PCV13 and PPSV23", "Meningococcal (MenACWY and MenB)", "Hib", "All of the above"]', 3, 'Asplenic children are at high risk for encapsulated bacteria. (Nelson)'),
    (v_topic_id, '93: What is the name of the system used in the US to report vaccine adverse events?', '["CDC-Report", "VAERS", "MedWatch", "Vax-Safety"]', 1, 'Vaccine Adverse Event Reporting System. (Harriet Lane)'),
    (v_topic_id, '94: Which of the following is a common "false" contraindication to vaccine?', '["History of anaphylaxis to vaccine", "Pregnancy", "Family history of an adverse event", "Severely low T-cells"]', 2, 'Family history is NOT a reason to withhold vaccines. (Case Files)'),
    (v_topic_id, '95: A child has "eczema." Is the smallpox vaccine (if ever needed) safe?', '["Yes", "No, risk of Eczema Vaccinatum", "Only if eczema is mild", "Only if given IM"]', 1, 'Patients with atopic dermatitis are at risk for disseminated infection with the vaccinia virus. (Nelson)'),
    (v_topic_id, '96: Which vaccine is given to prevent a disease that causes "paralytic" illness?', '["IPV", "PCV13", "MMR", "HepB"]', 0, 'Inactivated Poliovirus Vaccine (IPV) prevents Poliomyelitis. (Case Files)'),
    (v_topic_id, '97: Why was the Oral Polio Vaccine (OPV) replaced by IPV in the US?', '["OPV was too expensive", "OPV caused rare cases of Vaccine-Associated Paralytic Polio (VAPP)", "IPV is more effective", "IPV is easier to give"]', 1, 'Because the US is polio-free, the risk of VAPP from the live-attenuated OPV was greater than the risk of wild polio. (Nelson)'),
    (v_topic_id, '98: Which vaccine is recommended for a child traveling to an area with poor sanitation to prevent a common cause of food-borne jaundice?', '["HepB", "HepA", "MMR", "IPV"]', 1, 'Hepatitis A is transmitted via the fecal-oral route. (Harriet Lane)'),
    (v_topic_id, '99: Which vaccine provides protection against the most common cause of "croup"?', '["Hib", "Influenza", "No vaccine for common croup (Parainfluenza)", "PCV13"]', 2, 'Parainfluenza is the most common cause of croup, and there is no vaccine for it. (Case Files)'),
    (v_topic_id, '100: A child has a "severe" allergy to baker''s yeast. Which vaccine should be used with caution?', '["MMR", "Hepatitis B", "Varicella", "PCV13"]', 1, 'The HepB vaccine is produced using recombinant DNA in yeast cells. (Nelson)'),
    (v_topic_id, '101: Which of the following is the most appropriate way to decrease pain during injections?', '["Give Aspirin before visit", "Use topical lidocaine/prilocaine or ''the ShotBlocker''", "Hold the child down firmly", "Speed up the injection rate"]', 1, 'Topical anesthetics and distraction are effective. (Harriet Lane)'),
    (v_topic_id, '102: At what age should a pediatrician start screening for "depression" using a tool like the PHQ-9?', '["5 years", "10 years", "12 years", "18 years"]', 2, 'Universal annual depression screening is recommended starting at age 12. (AAP)'),
    (v_topic_id, '103: What is the "Rule of 2s" for Asthma preventive care in a well-child visit?', '["Coughing >2 times/week or waking >2 times/month", "2 doses of Albuterol", "2 inhalers", "None"]', 0, 'Symptoms more than twice a week or twice a month at night indicate persistent asthma needing a controller. (Nelson)'),
    (v_topic_id, '104: A 2-year-old child should have a vocabulary of approximately how many words?', '["50", "200", "500", "1000"]', 1, '2 years = 200 words, 2-word sentences, 50% intelligible. (Case Files)'),
    (v_topic_id, '105: At what age should a child be able to stack 6 blocks?', '["12 months", "18 months", "24 months", "3 years"]', 2, '24 months (2 years) = 6 blocks. (Harriet Lane)'),
    (v_topic_id, '106: At what age is "separation anxiety" most common and normal?', '["Birth", "9-18 months", "3 years", "5 years"]', 1, 'Separation anxiety is a normal part of developing attachment. (Nelson)'),
    (v_topic_id, '107: Which of the following is a sign of "readiness" for toilet training?', '["Being 18 months old", "Staying dry for 2 hours, interest in the potty, ability to follow 2-step commands", "Starting daycare", "Having a sibling who is trained"]', 1, 'Developmental readiness is more important than chronological age. (Case Files)'),
    (v_topic_id, '108: Most children are toilet trained by what age?', '["2 years", "3 years", "5 years", "1 year"]', 1, 'Most kids are daytime dry by age 3. (Nelson)'),
    (v_topic_id, '109: What is the most common cause of accidental poisoning in children?', '["Lead paint", "Household cleaners and medications", "Plants", "Spoiled food"]', 1, 'Common items in the home are the most frequent ingestants. (Harriet Lane)'),
    (v_topic_id, '110: "Secondary prevention" in pediatrics refers to:', '["Vaccinations", "Screening for conditions early (e.g., Lead, Vision)", "Treating a broken bone", "Hospice care"]', 1, 'Primary = Prevention; Secondary = Screening/Early Detection; Tertiary = Treatment/Rehab. (Nelson)');
